import "server-only";
import { randomUUID, timingSafeEqual } from "node:crypto";
import path from "node:path";
import { Client, type SFTPWrapper } from "ssh2";
import { photoDigest, VPS_IMAGE_ORIGIN } from "./drive-photo-processing";
import { readBoundedImage } from "./bounded-image-download";

export interface ImageTransfer {
  mkdir(directory: string): Promise<void>;
  read(file: string): Promise<Buffer | null>;
  writeExclusive(file: string, bytes: Buffer): Promise<void>;
  rename(from: string, to: string): Promise<void>;
  unlink(file: string): Promise<void>;
}

// Only names generated by processAndStoreDrivePhoto may enter the storage adapter.
export async function storeImmutablePhoto(transfer: ImageTransfer, root: string, relativePath: string, bytes: Buffer) {
  if (!/^produtos\/[a-f0-9]{2}\/[a-f0-9]{64}\/[1-6]-[a-f0-9]{64}\.jpg$/.test(relativePath)
    || !relativePath.endsWith(`-${photoDigest(bytes)}.jpg`)) throw new Error("Caminho de fotografia inválido.");
  const destination = path.posix.join(root, relativePath);
  let directory = root;
  for (const part of relativePath.split("/").slice(0, -1)) {
    directory = path.posix.join(directory, part);
    await transfer.mkdir(directory);
  }
  const verify = (stored: Buffer) => {
    if (photoDigest(stored) !== photoDigest(bytes)) throw new Error("Integridade do arquivo na VPS divergente.");
  };
  const existing = await transfer.read(destination);
  if (existing) { verify(existing); return; }
  const temporary = `${destination}.${randomUUID()}.part`;
  try {
    await transfer.writeExclusive(temporary, bytes);
    const uploaded = await transfer.read(temporary);
    if (!uploaded) throw new Error("Arquivo temporário não encontrado na VPS.");
    verify(uploaded);
    try { await transfer.rename(temporary, destination); }
    catch (error) {
      // Another invocation may have published exactly the same immutable content.
      const concurrent = await transfer.read(destination);
      if (!concurrent) throw error;
      verify(concurrent);
    }
    const final = await transfer.read(destination);
    if (!final) throw new Error("Arquivo definitivo não encontrado na VPS.");
    verify(final);
  } finally {
    // Never delete a final file: a timed-out database call may already reference it.
    await transfer.unlink(temporary);
  }
}

function sftpTransfer(sftp: SFTPWrapper): ImageTransfer {
  const done = (operation: (callback: (error?: Error | null) => void) => void) =>
    new Promise<void>((resolve, reject) => operation(error => error ? reject(error) : resolve()));
  return {
    mkdir: async directory => {
      try { await done(cb => sftp.mkdir(directory, { mode: 0o755 }, cb)); }
      catch (error) {
        const stats = await new Promise<import("ssh2").Stats>((resolve, reject) =>
          sftp.lstat(directory, (err, info) => err ? reject(err) : resolve(info)));
        if (!stats.isDirectory() || stats.isSymbolicLink()) throw error;
      }
    },
    read: file => new Promise((resolve, reject) => sftp.readFile(file, (error, data) => {
      if ((error as { code?: unknown })?.code === 2) resolve(null);
      else if (error) reject(error);
      else resolve(data);
    })),
    writeExclusive: (file, bytes) => done(cb => sftp.writeFile(file, bytes, { flag: "wx", mode: 0o644 }, cb)),
    rename: (from, to) => done(cb => sftp.rename(from, to, cb)),
    unlink: async file => {
      try { await done(cb => sftp.unlink(file, cb)); }
      catch (error) { if ((error as { code?: unknown }).code !== 2) throw error; }
    }
  };
}

export function vpsImageConfig(env: Record<string, string | undefined> = process.env) {
  const required = (name: string) => {
    const value = env[name]?.trim();
    if (!value) throw new Error(`Armazenamento VPS não configurado: ${name}.`);
    return value;
  };
  const host = required("VPS_IMAGES_SFTP_HOST");
  const username = required("VPS_IMAGES_SFTP_USER");
  const privateKey = Buffer.from(required("VPS_IMAGES_SFTP_KEY_BASE64"), "base64");
  const fingerprint = required("VPS_IMAGES_SFTP_HOST_SHA256").toLowerCase();
  const root = required("VPS_IMAGES_SFTP_ROOT");
  const port = Number(env.VPS_IMAGES_SFTP_PORT || 22);
  if (!/^[a-f0-9]{64}$/.test(fingerprint) || !root.startsWith("/") || root === "/"
    || root.includes("..") || !Number.isInteger(port) || port < 1 || port > 65535) throw new Error("Configuração SFTP inválida.");
  return { host, username, privateKey, fingerprint, root, port };
}

async function withVpsSftp(operation: (sftp: SFTPWrapper, root: string) => Promise<void>) {
  const config = vpsImageConfig();
  const client = new Client();
  await new Promise<void>((resolve, reject) => {
    let settled = false;
    const timer = setTimeout(() => { client.destroy(); reject(new Error("Tempo limite na transferência SFTP.")); }, 60_000);
    const finish = (error?: Error) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      error ? reject(error) : resolve();
      client.end();
    };
    client.on("error", finish);
    client.once("close", () => finish(new Error("Conexão SFTP encerrada.")));
    client.once("ready", () => client.sftp((error, sftp) => {
      if (error) return finish(error);
      operation(sftp, config.root).then(() => finish(), finish);
    }));
    try {
      client.connect({ host: config.host, port: config.port, username: config.username,
        privateKey: config.privateKey, readyTimeout: 15_000, keepaliveInterval: 10_000,
        hostHash: "sha256", hostVerifier: (hash: string) => /^[a-f0-9]{64}$/i.test(hash)
          && timingSafeEqual(Buffer.from(hash, "hex"), Buffer.from(config.fingerprint, "hex")) });
    } catch (error) { finish(error instanceof Error ? error : new Error("Configuração de chave SSH inválida.")); }
  });
}

export async function storeVpsImage(relativePath: string, bytes: Buffer) {
  await withVpsSftp((sftp, root) => storeImmutablePhoto(sftpTransfer(sftp), root, relativePath, bytes));
  // Confirm that the public read-only mapping serves the same bytes before persistence.
  const response = await fetch(VPS_IMAGE_ORIGIN + relativePath, { cache: "no-store", redirect: "error", signal: AbortSignal.timeout(15_000) });
  if (!response.ok || !response.headers.get("content-type")?.startsWith("image/jpeg")) throw new Error("Imagem VPS não disponível por HTTPS.");
  if (photoDigest(await readBoundedImage(response, bytes.length)) !== photoDigest(bytes)) throw new Error("Imagem HTTPS divergente do arquivo armazenado.");
}

// Called only for removed, confirmed-unreferenced assets. No directory removal.
export async function deleteVpsImage(relativePath: string) {
  if (!/^produtos\/([a-f0-9]{2})\/\1[a-f0-9]{62}\/[1-6]-[a-f0-9]{64}\.jpg$/.test(relativePath)) throw new Error("Caminho de exclusão inválido.");
  await withVpsSftp(async (sftp, root) => {
    const destination = path.posix.join(root, relativePath);
    const parts = destination.split("/").filter(Boolean);
    let checked = "";
    for (const [index, part] of parts.entries()) {
      checked += "/" + part;
      let stats: import("ssh2").Stats;
      try {
        stats = await new Promise((resolve, reject) => sftp.lstat(checked, (error, value) => error ? reject(error) : resolve(value)));
      } catch (error) {
        if ((error as { code?: unknown }).code === 2) return;
        throw error;
      }
      if (stats.isSymbolicLink() || (index < parts.length - 1 ? !stats.isDirectory() : !stats.isFile())) throw new Error("Exclusão bloqueada: caminho não é arquivo próprio regular.");
      if (index === parts.length - 1 && stats.size > 25 * 1024 * 1024) throw new Error("Exclusão bloqueada: tamanho de arquivo inesperado.");
    }
    const transfer = sftpTransfer(sftp);
    const bytes = await transfer.read(destination);
    if (!bytes) return;
    if (!relativePath.endsWith(`-${photoDigest(bytes)}.jpg`)) throw new Error("Exclusão bloqueada: conteúdo diverge do nome gerenciado.");
    await transfer.unlink(destination);
  });
}
